          },
          {
            "id": "p-workspace",
            "version": "KqlParameterItem/1.0",
            "name": "Workspace",
            "type": 5,
            "isHiddenWhenLocked": true,
            "value": "/subscriptions/708f712e-9b99-4b60-b830-048e5ebdcfde/resourceGroups/devteam-projectnour-rg/providers/Microsoft.OperationalInsights/workspaces/law-claraportemail"
          },
          {
            "id": "p-clinic",
            "version": "KqlParameterItem/1.0",
            "name": "ClinicFilter",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| distinct Clinic\n| order by Clinic asc",
            "crossComponentResources": [ "{Workspace}" ],
            "value": [ "value::all" ],
            "typeSettings": {
              "additionalResourceOptions": [ "value::all" ],
              "showDefault": false
