            "queryType": 0,
            "resourceType": "microsoft.operationalinsights/workspaces"
          },
          {
            "id": "p-status",
            "version": "KqlParameterItem/1.0",
            "name": "StatusFilter",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| distinct DeliveryStatus\n| order by DeliveryStatus asc",
            "crossComponentResources": [ "{Workspace}" ],
            "value": [ "value::all" ],
            "typeSettings": {
              "additionalResourceOptions": [ "value::all" ],
              "showDefault": false
            },
            "timeContext": { "durationMs": 604800000 },
            "queryType": 0,
            "resourceType": "microsoft.operationalinsights/workspaces"
          }
        ],
        "style": "pills",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces"
      },
      "name": "filters"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Delivered = countif(DeliveryStatus == \"Delivered\"), FailedOrBounced = countif(DeliveryStatus in (\"Bounced\", \"Failed\")), Suppressed = countif(DeliveryStatus in (\"Suppressed\", \"Quarantined\")), Total = count()\n| project Metric = pack_array(\"Delivered\", \"Failed / Bounced\", \"Suppressed / Quarantined\", \"Total Sent\"), Count = pack_array(Delivered, FailedOrBounced, Suppressed, Total)\n| mv-expand Metric to typeof(string), Count to typeof(long)",
        "size": 3,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [ "{Workspace}" ],
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": true,
          "titleContent": {
            "columnMatch": "Metric",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "Count",
            "formatter": 12,
            "formatOptions": { "palette": "blue" },
            "numberFormat": { "unit": 17, "options": { "maximumFractionDigits": 0 } }
          },
          "showBorder": true
        }
      },
      "name": "kpi-tiles"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by DeliveryStatus\n| order by Count desc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [ "{Workspace}" ],
        "visualization": "piechart",
        "chartSettings": {
          "xAxis": "DeliveryStatus",
          "yAxis": [ "Count" ],
          "showLegend": true
        }
      },
      "name": "pie-status"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by Clinic\n| order by Count desc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [ "{Workspace}" ],
        "visualization": "piechart",
        "chartSettings": {
          "xAxis": "Clinic",
          "yAxis": [ "Count" ],
          "showLegend": true
        }
      },
      "name": "pie-clinic"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by Clinic, DeliveryStatus\n| order by Clinic asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [ "{Workspace}" ],
        "visualization": "barchart",
        "chartSettings": {
          "xAxis": "Clinic",
          "yAxis": [ "Count" ],
          "group": "DeliveryStatus",
          "createOtherGroup": false,
          "showLegend": true
        }
      },
      "name": "column-clinic-status"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by bin(TimeGenerated, 12h), DeliveryStatus\n| order by TimeGenerated asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [ "{Workspace}" ],
        "visualization": "linechart",
        "chartSettings": {
          "xAxis": "TimeGenerated",
          "yAxis": [ "Count" ],
          "group": "DeliveryStatus",
          "showLegend": true
        }
